// =====================================================================
// WF3 - Definir el periodo del reporte: las últimas 24 horas.
// $now usa la zona horaria configurada en n8n (America/Guatemala).
// =====================================================================
const fin = $now;
const inicio = $now.minus({ hours: 24 });

return [{
  json: {
    periodo_inicio: inicio.toISO(),
    periodo_fin: fin.toISO(),
    nombre_archivo: `reporte_tickets_${fin.toFormat('yyyyMMdd_HHmm')}.csv`,
  },
}];

// =====================================================================
// WF3 - Armar el contenido del CSV
// Seguridad: protege contra "inyección de fórmulas" (CSV injection).
// Si una celda empieza con = + - @, Excel la ejecutaría como fórmula;
// se le antepone un apóstrofo para que se muestre como texto.
// =====================================================================
const filas = $input.all().map(i => i.json).filter(f => f.codigo);
const periodo = $('Definir periodo').first().json;

function celda(valor) {
  let texto = String(valor ?? '');
  if (/^[=+\-@\t\r]/.test(texto)) texto = "'" + texto;
  return '"' + texto.replace(/"/g, '""') + '"';
}

const columnas = ['Codigo', 'Fecha', 'Departamento', 'Asunto', 'Categoria', 'Prioridad', 'Estado'];
const lineas = [columnas.map(celda).join(',')];

for (const f of filas) {
  lineas.push([f.codigo, f.fecha, f.departamento, f.asunto,
               f.categoria, f.prioridad, f.estado].map(celda).join(','));
}
if (filas.length === 0) {
  lineas.push(celda('Sin tickets en el periodo'));
}

// \uFEFF (BOM) permite que Excel muestre bien las tildes y la ñ
return [{
  json: {
    csv: '\uFEFF' + lineas.join('\r\n'),
    total: filas.length,
    nombre_archivo: periodo.nombre_archivo,
  },
}];
